        /// <summary>Returns the exact independently frozen UTF8 reference bytes; verifies their original raw SHA256.</summary>
        public static byte[] FixedGoldenBytes()
        {
            byte[] packed=Convert.FromBase64String(string.Concat(goldenGzipBase64));
            using(var input=new MemoryStream(packed))using(var gzip=new System.IO.Compression.GZipStream(input,System.IO.Compression.CompressionMode.Decompress))using(var output=new MemoryStream())
            {gzip.CopyTo(output);var raw=output.ToArray();using(var hash=System.Security.Cryptography.SHA256.Create())if(string.Concat(hash.ComputeHash(raw).Select(b=>b.ToString("x2",CultureInfo.InvariantCulture)))!="ee0ef35bd3dbf03396fc5fd30389b9e75e486f8b08982b2efde3ffec1cba4ed0")throw new InvalidOperationException("FIXED_GOLDEN_RAW_HASH_MISMATCH");return raw;}
        }
        private static readonly Lazy<FixtureJson> fixedBundle=new Lazy<FixtureJson>(()=>FixtureJson.Parse(System.Text.Encoding.UTF8.GetString(FixedGoldenBytes())));
        internal static FixtureJson Bundle=>fixedBundle.Value;
