        public static object? Property(object instance,string name)=>instance.GetType().GetProperty(name)!.GetValue(instance);
        internal static object? Invoke(object instance,string name,params object?[] args)=>instance.GetType().GetMethods().Single(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(instance,args);
        private static Type App(string name)=>Assembly.Load("STP.Application").GetType("STP.Application."+name,true)!;
        private static object AppNew(string name,params object?[] args)=>Activator.CreateInstance(App(name),args)!;
        private static object AppFixture(string method,params object[] args)=>Assembly.Load("STP.Tests.Application.EditMode").GetType("STP.Tests.Application.EditMode.LocalSaveContractFixtures",true)!.GetMethod(method)!.Invoke(null,args)!;
        /// <summary>Returns a real explicitly bound empty or alternative immutable profile snapshot.</summary>
        public static object Snapshot(long generation=1,bool alternative=false)=>AppFixture("CreateContractSnapshot",generation,alternative);
        /// <summary>Wraps an actual supplied payload and preserves its reference for commit acknowledgement tests.</summary>
