        public static byte[] Canonical(string text){var ports=Ports();var r=ports[0].GetType().GetInterfaces().Single(t=>t.Name=="ICanonicalJson").GetMethod("Canonicalize")!.Invoke(ports[0],new[]{(object)Encoding.UTF8.GetBytes(text),AppNew("JsonResourceLimits",67108864,64,65536,1048576,256)})!;return(byte[])Invoke(r,"GetUtf8")!;}
        private static object[] Ports()=>(object[])AppFixture("CreateContractPorts");
