        private static object Catalog(FixtureJson c)=>AppNew("CatalogIdentity",c.Get("catalogId").Text,(int)c.Get("revision").Integer,c.Get("hashSha256").Text,Enum.Parse(App("CatalogUse"),c.Get("use").Text),Enum.Parse(App("CatalogApprovalStatus"),c.Get("approvalStatus").Text));
        private static object CatalogSet(FixtureJson s,object json)=>App("CatalogSetIdentity").GetMethod("Create")!.Invoke(null,new[]{Catalog(s.Get("publicCatalog")),Catalog(s.Get("campaignCatalog")),Catalog(s.Get("completionCatalog")),Catalog(s.Get("aggregateCatalog")),json})!;
        internal static LocalSaveCodec CodecFor(FixtureJson c)
        {
            var ports=Ports();object json=ports[0],profile=ports[1],catalogs=ports[2],puzzles=ports[3],campaign=ports[4],completion=ports[5];var descriptors=c.Maybe("passiveBindings")?.Items??Array.Empty<FixtureJson>();var use=Property(profile,"Use")!;
            var privacy=descriptors.Where(x=>x.Get("recordKind").Text=="PRIVACY").Select(x=>(object)new RetainedPrivacyBinding(x.Get("policyRevision").Text,x.Get("sdkContractRevision").Text,x.Get("source").Text)).ToArray();var iap=descriptors.Where(x=>x.Get("recordKind").Text=="IAP").Select(x=>(object)new RetainedIapBinding(x.Get("policyVersion").Text,x.Get("store").Text,x.Get("logicalProductKey").Text)).ToArray();var legacy=descriptors.Where(x=>x.Get("recordKind").Text=="LEGACY_OWNERSHIP").Select(x=>(object)new RetainedLegacyOwnershipReader(x.Get("readerId").Text,(int)x.Get("sourceSaveSchemaVersion").Integer,x.Get("itemTypes").Items.Select(v=>v.Text).ToArray())).ToArray();var cosmetics=descriptors.Where(x=>x.Get("recordKind").Text=="COSMETICS").Select(x=>typeof(RetainedCosmeticsBinding).GetMethod("FromDocuments")!.Invoke(null,new[]{(object)x.Get("document").Canonical(),x.Get("campaignDocument").Canonical(),json,use,puzzles})!).ToArray();
            string[] Policies(string kind,string property)=>descriptors.Where(x=>x.Get("recordKind").Text==kind).Select(x=>x.Get(property).Text).Distinct(StringComparer.Ordinal).ToArray();
            var retained=Activator.CreateInstance(typeof(RetainedContractBindings),use,Policies("HINT","policyVersion"),Policies("DAILY","policyVersion"),Policies("ACCESSIBILITY","contractRevision"),Typed(typeof(RetainedPrivacyBinding),privacy),Typed(typeof(RetainedIapBinding),iap),Typed(typeof(RetainedLegacyOwnershipReader),legacy),Typed(typeof(RetainedCosmeticsBinding),cosmetics),descriptors.Where(x=>x.Get("recordKind").Text=="REWARD"||x.Get("recordKind").Text=="ENDLESS_REWARD").Select(x=>x.Get("policyVersion").Text).Distinct(StringComparer.Ordinal).ToArray(),Policies("ENDLESS_PARAMETERS","generatorVersion"),new[]{"de-DE"},new[]{"contract-master"},Typed(typeof(RetainedCompletionRewardBinding),descriptors.Where(x=>x.Get("recordKind").Text=="REWARD").Select(x=>typeof(RetainedCompletionRewardBinding).GetMethod("FromDocument")!.Invoke(null,new[]{(object)x.Get("policyVersion").Text,Bundle.Get("catalogs").Get("completionCatalog").Canonical(),json,use})!)),Array.Empty<RetainedProgressCatalogBinding>())!;
            var historical=new List<object>();var binding=c.Get("bindings");if(c.Get("sourceSchemaVersion").Integer==1)
            {
                var levelBindings=new List<object>();var docs=new[]{binding}.Concat(binding.Maybe("additionalLevelBindings")?.Items??Array.Empty<FixtureJson>());foreach(var d in docs){var source=d.Maybe("sourceDocument");if(source==null)continue;var target=d.Get("targetDocument");var locked=binding.Get("releaseLock");levelBindings.Add(typeof(HistoricalLevelBinding).GetMethod("Create")!.Invoke(null,new[]{(object)Encoding.UTF8.GetBytes(source.Get("canonicalUtf8").Text),source.Get("jcsSha256").Text,Encoding.UTF8.GetBytes(target.Get("canonicalUtf8").Text),target.Get("jcsSha256").Text,Encoding.UTF8.GetBytes(locked.Get("canonicalUtf8").Text),locked.Get("jcsSha256").Text,json})!);}
                var destination=CatalogSet(binding.Get("destinationCatalogSet"),json);var sourceCampaign=typeof(HistoricalProfileBinding).GetMethod("ReadSourceCampaign")!.Invoke(null,new[]{(object)Bundle.Get("catalogs").Get("oldCampaign").Canonical(),binding.Get("sourceContentCatalogHash").Text,json,use,puzzles})!;historical.Add(Activator.CreateInstance(typeof(HistoricalProfileBinding),binding.Get("sourceLocalProfileId").Text,binding.Get("sourceContentCatalogHash").Text,profile,destination,Typed(typeof(HistoricalLevelBinding),levelBindings),sourceCampaign,binding.Get("ledgerAlgorithm").Text)!);
            }
            var oldReaders=new List<object>();var old=c.Maybe("legacyReaderBinding");if(old!=null&&old.Maybe("readerId")!=null)oldReaders.Add(Activator.CreateInstance(typeof(LegacyV2ReaderBinding),old.Get("readerId").Text,old.Get("sourceEnvelopeSha256").Text,old.Get("sourcePayloadSha256").Text,old.Get("sourceContentCatalogHash").Text,use)!);
            return(LocalSaveCodec)Activator.CreateInstance(typeof(LocalSaveCodec),json,profile,catalogs,puzzles,campaign,completion,retained,Typed(typeof(HistoricalProfileBinding),historical),Typed(typeof(LegacyV2ReaderBinding),oldReaders))!;
        }
        internal static string Sha(byte[] source){using(var h=System.Security.Cryptography.SHA256.Create())return string.Concat(h.ComputeHash(source).Select(x=>x.ToString("x2",CultureInfo.InvariantCulture)));}
        internal static byte[] MutatePayload(FixtureJson c,Func<string,string> mutation,bool expected=false)
        {string p=c.Get(expected?"expectedPayloadUtf8":"sourcePayloadUtf8").Text;string e=c.Get(expected?"expectedEnvelopeUtf8":"sourceEnvelopeUtf8").Text;string old=c.Get(expected?"expectedPayloadSha256":"sourcePayloadSha256").Text;string next=Encoding.UTF8.GetString(Canonical(mutation(p)));return Encoding.UTF8.GetBytes(e.Replace("\"payload\":"+p,"\"payload\":"+next).Replace("\"payloadSha256\":\""+old+"\"","\"payloadSha256\":\""+Sha(Encoding.UTF8.GetBytes(next))+"\""));}
        /// <summary>Real codec configured with the complete historical first-clear fixture line and no operative providers.</summary>
        public static LocalSaveCodec Codec()=>CodecFor(Case("V1_FULL_FIRST_CLEAR"));
        /// <summary>Returns exact fixed original full-v1 source bytes for migration-source tests.</summary>
        public static byte[] V1Source()=>Encoding.UTF8.GetBytes(Case("V1_FULL_FIRST_CLEAR").Get("sourceEnvelopeUtf8").Text);
        /// <summary>Encodes an offered snapshot through the actual codec using explicit deterministic diagnostics.</summary>
        public static byte[] Encode(LocalSaveCodec codec,object snapshot)=> (byte[])typeof(LocalSaveCodec).GetMethod("Encode")!.Invoke(codec,new[]{snapshot,(object)"2026-10-19T00:00:00Z","contract-1","contract-node-reference"})!;
